script:
frappe.ui.pages['ワークスペース'] || true; 

// تعريف كود الـ CSS المخصص
const customWorkspaceStyles = `
    /* تغيير خلفية صفحة مساحة العمل بالكامل إلى اللون البنفسجي الداكن */
    .desk-page-container, .workspace-page, .desk-container {
        background-color: #3b3395 !important;
        color: #ffffff !important;
    }

    /* تعديل شكل العناوين والنصوص لتتناسب مع الخلفية المظلمة */
    .page-title, .title-text, .widget-head {
        color: #ffffff !important;
    }

    /* تحويل المربعات والاختصارات إلى بطاقات ذات حواف دائرية ناعمة */
    .widget-shortcut-box, .widget-card-box, .shortcut-widget-box {
        border-radius: 20px !important;
        border: none !important;
        box-shadow: 0px 4px 15px rgba(0, 0, 0, 0.2) !important;
        transition: transform 0.2s ease-in-out, box-shadow 0.2s ease-in-out !important;
    }

    /* تأثير حركة خفيف عند تمرير الفأرة فوق الأيقونات */
    .widget-shortcut-box:hover, .shortcut-widget-box:hover {
        transform: translateY(-5px) !important;
        box-shadow: 0px 8px 20px rgba(0, 0, 0, 0.3) !important;
    }

    /* أمثلة لتغيير ألوان خلفيات البطاقات بناءً على اسم الموديول */
    [data-widget-name="Buying"] .widget-shortcut-box, [data-link-to="Buying"] { background-color: #d1342a !important; }
    [data-widget-name="Stock"] .widget-shortcut-box, [data-link-to="Stock"] { background-color: #f1a123 !important; }
    [data-widget-name="Customer"] .widget-shortcut-box, [data-link-to="Customer"] { background-color: #2ca56d !important; }
`;

// إدراج الـ CSS داخل الـ Head الخاص بالصفحة
$("<style>")
    .prop("type", "text/css")
    .html(customWorkspaceStyles)
    .appendTo("head");

frappe.ui.form.on('Workspace', {
    refresh: function(frm) {
        // الانتظار قليلاً للتأكد من نزول عناصر لوحة التحكم في المتصفح
        setTimeout(() => {
            apply_arm_custom_onboarding();
        }, 300);
    }
});

function apply_arm_custom_onboarding() {
    let $default_container = $('.workspace-onboarding-container, .onboarding-container');

    // إذا عثرنا على الواجهة القديمة المبعثرة
    if ($default_container.length && !$default_container.hasClass('arm-modified')) {
        $default_container.addClass('arm-modified');

        // قراءة النصوص الحالية ديناميكياً لتطابق أي موديول
        let title = $default_container.find('.onboarding-title, h4, h3').first().text().trim() || "إدارة العملاء";
        let subtitle = $default_container.find('.subtitle, p').first().text().trim() || "شركة آرم للمقاولات والعمارة";

        // تجميع المهام والخطوات المطبوعة حالياً في النظام
        let steps_data = [];
        $default_container.find('.onboarding-step, .step-container, .list-group-item, .step-title-container').each(function() {
            let step_title = $(this).find('.step-title, .title, span, a').first().text().trim();
            let is_done = $(this).find('.step-status-icon.complete, .fa-check-circle, .checked, svg.text-success, [data-status="complete"]').length > 0;
            
            if (step_title && step_title !== "تخطى" && step_title !== "رفض") {
                steps_data.push({ title: step_title, is_complete: is_done });
            }
        });

        // مصفوفة احتياطية مطابقة لبياناتك الظاهرة في الصورة السابقة
        if (steps_data.length === 0) {
            steps_data = [
                { title: "Introduction to CRM", is_complete: true },
                { title: "إنشاء عميل محتمل", is_complete: true },
                { title: "Create Opportunity", is_complete: false },
                { title: "Create and Send Quotation", is_complete: false },
                { title: "CRM Settings", is_complete: false }
            ];
        }

        // الحسابات الرياضية لشريط التقدم
        let total_steps = steps_data.length;
        let done_count = steps_data.filter(s => s.is_complete).length;
        let progress_pct = total_steps > 0 ? Math.round((done_count / total_steps) * 100) : 40;

        // بناء الهيكل البنفسجي الاحترافي المخصص لشركة ARM
        let arm_html = `
            <div class="ob-wrap" id="arm-global-onboarding">
                <div class="ob-header">
                    <div class="ob-avatar"><i class="fa fa-users" aria-hidden="true"></i></div>
                    <div>
                        <div class="ob-title">${title}</div>
                        <div class="ob-sub">${subtitle}</div>
                    </div>
                    <button class="ob-dismiss" id="armDismissBtn">تجاهل</button>
                </div>

                <div class="ob-progress-row">
                    <div class="ob-bar-wrap"><div class="ob-bar-fill" style="width: ${progress_pct}%"></div></div>
                    <div class="ob-progress-label">${done_count} من ${total_steps} مكتملة</div>
                </div>

                <div class="ob-steps" id="armStepsList"></div>

                <div class="ob-footer">
                    <span class="ob-footer-note" id="armFooterNote">اضغط على أي خطوة لتحديد حالتها وتفعيلها</span>
                    <button class="ob-btn" id="armNextBtn"><i class="fa fa-arrow-left" aria-hidden="true"></i> الخطوة التالية</button>
                </div>
            </div>
        `;

        // إزالة الهيكل القديم تماماً واستبداله بالتصميم الجديد
        $default_container.html(arm_html);

        // حقن بطاقات الخطوات بالتصميم الجديد
        const $list = $('#armStepsList');
        let current_active_found = false;

        steps_data.forEach((step, index) => {
            let status = 'pending';
            if (step.is_complete) {
                status = 'done';
            } else if (!current_active_found) {
                status = 'active';
                current_active_found = true;
            }

            let step_html = `
                <div class="ob-step ${status}" data-index="${index}">
                    <div class="snum ${status}">
                        ${status === 'done' ? '<i class="fa fa-check" style="font-size:12px" aria-hidden="true"></i>' : (index + 1)}
                    </div>
                    <div class="stext">
                        ${step.title}
                        <div class="stext-sub" ${status === 'active' ? 'style="color:#534AB7"' : ''}>
                            ${status === 'active' ? 'الخطوة الحالية — ابدأ هنا' : 'خطوة تهيئة للنظام'}
                        </div>
                    </div>
                    <span class="sbadge ${status}">
                        ${status === 'done' ? 'مكتمل' : (status === 'active' ? 'جارٍ' : 'قادم')}
                    </span>
                </div>
            `;
            $list.append(step_html);
        });

        // ربط الأزرار والبطاقات برمجياً لتنفيذ المهام الأصلية للنظام
        $('#armDismissBtn').on('click', function() {
            $default_container.fadeOut();
            $default_container.find('.btn-onboarding-skip, .dismiss, button:contains("رفض"), button:contains("تخطى")').first().click();
        });

        $('.ob-step').on('click', function() {
            let idx = $(this).data('index');
            // نقر برمجي على الخطوة المخفية المقابلة لتوجيه المستخدم للـ DocType المناسب
            $('.workspace-onboarding-container, .onboarding-container').find('.onboarding-step, button, a, .step-title-container').eq(idx).click();
        });
    }
}

// استخدام مراقب فوري للـ DOM لضمان استدعاء الدالة حتى لو تأخر تحميل الصفحة
const arm_observer = new MutationObserver(() => {
    if ($('.workspace-onboarding-container, .onboarding-container').length) {
        apply_arm_custom_onboarding();
    }
});
arm_observer.observe(document.body, { childList: true, subtree: true });

// --- بداية الكود ---

frappe.ui.form.on('Building Survey', {
    refresh: function(frm) {

        // إخفاء الحقول الفردية فقط لتجنب إخفاء قسم التصميم بالكامل
        frm.toggle_display([
            'full_name', 'phone', 'email', 'current_residence', 'city',
            'project_location', 'has_sketch', 'has_autocad',
            'size_family', 'couples', 'grandchildren',
            'girls_under_10', 'boys_under_10',
            'girls_above_14', 'boys_above_14', 'haya'
        ], false);

        render_custom_survey(frm);
    }
});

function render_custom_survey(frm) {

    let wrapper = frm.get_field('survey_ui');
    if (!wrapper) return;

    // 1. CSS
    let css = `
    <style>
        .custom-survey-wrapper {
            direction: rtl;
            font-family: 'Tajawal', 'Cairo', sans-serif;
            background-color: #f8f9fa;
            padding: 20px;
            color: #333;
        }
        .survey-header-main {
            background-color: #a8b2bc;
            color: #2c3e50;
            padding: 15px;
            font-size: 24px;
            font-weight: bold;
            text-align: right;
            border-radius: 8px 8px 0 0;
            margin-bottom: 20px;
            display: flex;
            align-items: center;
        }
        .survey-section {
            border: 2px solid #5c6c7f;
            border-radius: 8px;
            background: #fff;
            margin-bottom: 20px;
            overflow: hidden;
        }
        .section-title {
            background-color: #5c6c7f;
            color: #fff;
            padding: 10px 15px;
            font-size: 18px;
            font-weight: bold;
            display: inline-block;
            border-radius: 0 0 0 8px;
        }
        .section-content {
            padding: 15px;
        }
        .form-row-custom {
            display: flex;
            align-items: center;
            margin-bottom: 12px;
            border-bottom: 1px dashed #e2e8f0;
            padding-bottom: 8px;
        }
        .form-row-custom label {
            flex: 1;
            font-weight: bold;
            color: #2c3e50;
            margin: 0;
            font-size: 14px;
        }
        .form-row-custom input,
        .form-row-custom select {
            flex: 2;
            border: none;
            border-bottom: 1px solid #ccc;
            background: transparent;
            padding: 5px;
            outline: none;
            font-family: inherit;
        }
        .grid-2-cols {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 15px;
        }
    </style>
    `;

    // 2. HTML
    let html = `
    <div class="custom-survey-wrapper">

        <div class="survey-header-main">
            نموذج استبيان مبنى سكني
        </div>

        <div style="display:grid;grid-template-columns:1fr 1fr;gap:20px;">

            <!-- المشروع -->
            <div>
                <div class="survey-section">
                    <div class="section-title">معلومات خاصة بالمشروع</div>
                    <div class="section-content">

                        <div class="form-row-custom">
                            <label>أين يقع المشروع</label>
                            <input id="ui_project_location" value="${frm.doc.project_location || ''}">
                        </div>

                        <div class="form-row-custom">
                            <label>هل يوجد رسم كروكي</label>
                            <select id="ui_has_sketch">
                                <option ${frm.doc.has_sketch == "نعم" ? "selected" : ""}>نعم</option>
                                <option ${frm.doc.has_sketch == "لا" ? "selected" : ""}>لا</option>
                            </select>
                        </div>

                        <div class="form-row-custom">
                            <label>AutoCAD</label>
                            <select id="ui_has_autocad">
                                <option ${frm.doc.has_autocad == "نعم" ? "selected" : ""}>نعم</option>
                                <option ${frm.doc.has_autocad == "لا" ? "selected" : ""}>لا</option>
                            </select>
                        </div>

                    </div>
                </div>
            </div>

            <!-- التواصل -->
            <div>
                <div class="survey-section">
                    <div class="section-title">معلومات التواصل</div>
                    <div class="section-content">

                        <div class="form-row-custom">
                            <label>الإسم</label>
                            <input id="ui_full_name" value="${frm.doc.full_name || ''}">
                        </div>

                        <div class="form-row-custom">
                            <label>الهاتف</label>
                            <input id="ui_phone" value="${frm.doc.phone || ''}">
                        </div>

                        <div class="form-row-custom">
                            <label>الإيميل</label>
                            <input id="ui_email" value="${frm.doc.email || ''}">
                        </div>

                        <div class="form-row-custom">
                            <label>السكن</label>
                            <input id="ui_current_residence" value="${frm.doc.current_residence || ''}">
                        </div>

                        <div class="form-row-custom">
                            <label>المدينة</label>
                            <input id="ui_city" value="${frm.doc.city || ''}">
                        </div>

                    </div>
                </div>
            </div>

        </div>

    </div>
    `;

    wrapper.$wrapper.html(css + html);

    bind_survey_events(frm, wrapper.$wrapper);
}

function bind_survey_events(frm, $wrapper) {

    const fields = [
        'full_name','phone','email','current_residence','city',
        'project_location'
    ];

    fields.forEach(field => {
        $wrapper.find(`#ui_${field}`).on('change', function() {
            frm.set_value(field, $(this).val());
        });
    });

    const selects = ['has_sketch','has_autocad'];

    selects.forEach(field => {
        $wrapper.find(`#ui_${field}`).on('change', function() {
            frm.set_value(field, $(this).val());
        });
    });
}

// --- نهاية الكود ---

// يمكنك وضع هذا الكود في ملف JS مخصص أو حقنه عبر Client Script عام
frappe.provide("frappe.ui");

$(document).ready(function() {
    // كود CSS المخصص لكروت الأرقام بهوية الأبيض والأسود
    const numberCardTheme = `
        /* استهداف حاوية كرت الأرقام */
        .widget.number-widget-box,
        .widget.number-card {
            background-color: #ffffff !important;
            border: 1px solid #e5e5e5 !important;
            border-bottom: 4px solid #000000 !important; /* خط هندسي أسود سفلي */
            border-radius: 8px !important;
            box-shadow: 0 4px 10px rgba(0, 0, 0, 0.02) !important;
            transition: all 0.3s ease !important;
            position: relative;
            overflow: hidden;
        }

        /* تأثير التحويم (Hover) لإعطاء ديناميكية مودرن */
        .widget.number-widget-box:hover,
        .widget.number-card:hover {
            transform: translateY(-4px) !important;
            box-shadow: 0 10px 20px rgba(0, 0, 0, 0.08) !important;
            border-bottom: 4px solid #333333 !important;
        }

        /* تنسيق عنوان الكرت (المسمى) */
        .widget .widget-title,
        .widget.number-card .card-heading {
            color: #666666 !important; /* رمادي داكن للتباين */
            font-weight: 600 !important;
            font-size: 14px !important;
            letter-spacing: 0.2px;
        }

        /* تنسيق الرقم الفعلي المعروض */
        .widget .widget-value,
        .widget.number-card .number-card-value {
            color: #000000 !important; /* أسود صريح */
            font-weight: 800 !important;
            font-size: 30px !important;
            letter-spacing: -0.5px !important;
            margin-top: 8px !important;
        }

        /* تنسيق مؤشر النسبة المئوية (Indicator) إن وُجد */
        .widget .indicator-pill {
            background-color: #f4f4f5 !important;
            color: #000000 !important;
            border: 1px solid #e5e5e5 !important;
            font-weight: 600 !important;
            border-radius: 4px !important; /* زوايا شبه حادة */
        }
        
        /* تأثير خطوط معمارية خفيفة جداً في الخلفية للكرت (اختياري) */
        .widget.number-widget-box::before,
        .widget.number-card::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 50px;
            height: 100%;
            background: repeating-linear-gradient(
                45deg,
                transparent,
                transparent 5px,
                rgba(0, 0, 0, 0.02) 5px,
                rgba(0, 0, 0, 0.02) 6px
            );
            pointer-events: none;
            opacity: 0;
            transition: opacity 0.3s ease;
        }

        .widget.number-widget-box:hover::before,
        .widget.number-card:hover::before {
            opacity: 1; /* تظهر الخطوط الهندسية عند تمرير الماوس فقط */
        }
    `;

    // حقن الكود مباشرة في رأس الصفحة
    $('<style id="custom-number-cards-theme"></style>')
        .html(numberCardTheme)
        .appendTo('head');
});

frappe.ui.form.on('Building Survey', {

    refresh: function(frm) {
        toggle_relation_field(frm);
    },

    kitchen_type: function(frm) {
        toggle_relation_field(frm);
        suggest_relation(frm);
    },

    living_type: function(frm) {
        toggle_relation_field(frm);
        suggest_relation(frm);
    },

    dining_type: function(frm) {
        suggest_relation(frm);
    }
});


// 🎯 إظهار/إخفاء relation_type بشكل صحيح
function toggle_relation_field(frm) {

    let kitchen = frm.doc.kitchen_type;
    let living = frm.doc.living_type;

    // يظهر إذا أي واحد من الاثنين Open Space
    if (
        kitchen === "مطبخ مفتوح" ||
        living === "فراغ مفتوح"
    ) {
        frm.set_df_property("relation_type", "hidden", 0);
    } else {
        frm.set_df_property("relation_type", "hidden", 1);
        frm.set_value("relation_type", "");
    }
}


// 🤖 اقتراح العلاقات
function suggest_relation(frm) {

    let kitchen = frm.doc.kitchen_type;
    let living = frm.doc.living_type;
    let dining = frm.doc.dining_type;

    // 🔥 كامل Open Space
    if (
        kitchen === "مطبخ مفتوح" &&
        living === "فراغ مفتوح" &&
        dining === "فراغ مفتوح"
    ) {
        frm.set_value("relation_type", "المعيشة مفتوحة على المطبخ والأكل");
        return;
    }

    // 🔥 معيشة + أكل
    if (
        living === "فراغ مفتوح" &&
        dining === "فراغ مفتوح"
    ) {
        frm.set_value("relation_type", "المعيشة مفتوحة على الأكل");
        return;
    }

    // 🔥 مطبخ + معيشة
    if (
        kitchen === "مطبخ مفتوح" &&
        living === "فراغ مفتوح"
    ) {
        frm.set_value("relation_type", "مطبخ مفتوح على المعيشة");
        return;
    }

    // 🔥 مطبخ + أكل
    if (
        kitchen === "مطبخ مفتوح" &&
        dining === "فراغ مفتوح"
    ) {
        frm.set_value("relation_type", "مطبخ مفتوح على الأكل");
        return;
    }
}

frappe.ui.form.on('HD Ticket', {
    remote_desktop: function(frm) {
        // جلب الـ IP من حقل ip_device
        var ip = frm.doc.ip_device;
        
        if (ip) {
            // فتح الرابط باستخدام البروتوكول rdp://
            window.location.href = 'rdp://' + ip;
            
            // إظهار تنبيه للمستخدم
            frappe.show_alert({
                message: __('Opening Remote Desktop for ' + ip),
                indicator: 'green'
            });
        } else {
            // رسالة في حال كان الحقل فارغاً
            frappe.msgprint(__('IP Device field is empty. Please ensure the IP is captured first.'));
        }
    }
});

frappe.ui.form.on('HD Ticket', {
    refresh: function (frm) {
        // Add custom behavior if needed
    },
    remote_desktop: function (frm) {
        if (frm.doc.ip_device) {
            // رابط التطبيق المحلي الخاص بك على البورت 8088
            const local_scanner_url = `http://localhost:8088/?ip=${frm.doc.ip_device}`;
            // فتح الرابط في نافذة جديدة
            window.open(local_scanner_url, '_blank');
            frappe.show_alert({
                message: __('جاري محاولة الاتصال بـ {0}...', [frm.doc.ip_device]),
                indicator: 'blue'
            });
        } else {
            frappe.msgprint(__('يرجى التأكد من وجود عنوان IP في حقل IP Device'));
        }
    }
});

frappe.ui.workspace['المخزن'] = {
    title: __('المخزن'),
    icon: 'octicon octicon-package',
    color: '#4CAF50',
    short_cuts: [
        { type: 'doctype', name: 'Warehouse', label: __('المخازن'), color: '#FF9800', icon: 'octicon octicon-home' },
        { type: 'doctype', name: 'Item', label: __('الأصناف'), color: '#03A9F4', icon: 'octicon octicon-box' },
        { type: 'doctype', name: 'BOM', label: __('المواد المركبة'), color: '#9C27B0', icon: 'octicon octicon-gear' },
        { type: 'doctype', name: 'Stock Entry', label: __('إدخال كمية للمخزن'), color: '#8BC34A', icon: 'octicon octicon-sync' },
        { type: 'doctype', name: 'Purchase Order', label: __('أمر شراء'), color: '#FF5722', icon: 'octicon octicon-credit-card' },
        { type: 'doctype', name: 'Purchase Request', label: __('طلب مواد'), color: '#00BCD4', icon: 'octicon octicon-list-unordered' }
    ],
