async function update_technical_content(frm, readonly = false) {

    const checkbox_map = [
        { field: "mash", title: "وصف المشروع" },
        { field: "fan",  title: "العرض الفني" },
        { field: "m1",   title: "المرحلة الأولى" },
        { field: "m2",   title: "المرحلة الثانية" },
        { field: "m3",   title: "المرحلة الثالثة" },
        { field: "mal",  title: "العرض المالي" }
    ];

    let final_content = `
        <style>
            .ql-editor { direction: rtl !important; text-align: right !important; }
            .custom-title-box {
                position: relative !important;
                display: inline-block !important;
                background-color: #000000 !important;
                color: #ffffff !important;
                padding: 4px 15px !important;
                font-weight: bold !important;
                font-size: 15px !important;
                border-radius: 2px !important;
                z-index: 5 !important;
                margin-bottom: 10px !important;
            }
            .custom-title-box::after {
                content: "" !important;
                position: absolute !important;
                top: 0 !important;
                right: 100% !important;
                width: 1500px !important;
                height: 100% !important;
                background-image: repeating-linear-gradient(45deg,#000,#000 2px,transparent 2px,transparent 6px) !important;
                z-index: -1 !important;
            }
        </style>
        <div style="direction:rtl;text-align:right;font-family:Tahoma,Arial;font-size:14px;line-height:1.8;color:#000;">
    `;

    for (let row of checkbox_map) {
        if (frm.doc[row.field]) {
            let r = await frappe.db.get_value(
                "template arm",
                { titlee: row.title },
                ["titlee", "contactt"]
            );

            if (r && r.message) {
                let title = r.message.titlee;
                let text  = r.message.contactt || "";

                text = text.replace(/{{customer_name}}/g, frm.doc.customer_name || "");
                text = text.replace(/{{project_name}}/g,  frm.doc.project_name  || "");

                if (row.field === "mal") {
                    let prices = frm.doc.ard || [];
                    let min_price_from = null;

                    prices.forEach(rw => {
                        if (rw.price_from != null && (min_price_from === null || rw.price_from < min_price_from))
                            min_price_from = rw.price_from;
                    });

                    text = text.replace(/{{price_from}}/g, min_price_from ?? 0);

                    text += `
                        <div style="margin-top:20px;text-align:right;">
                            <p><strong>السعر الإجمالي:</strong> ${frm.doc.total_from || 0}</p>
                        </div>
                    `;
                }

                final_content += `
                    <div style="margin-bottom:35px;text-align:right;clear:both;">
                        <div style="margin-bottom:12px;">
                            <span class="custom-title-box">${title}</span>
                        </div>
                        <div style="padding-right:15px;text-align:right;">${text}</div>
                    </div>
                `;
            }
        }
    }

    final_content += "</div>";

    if (readonly) return;

    const current = (frm.doc.ardtxt || "").replace(/\s+/g, " ").trim();
    const updated  = final_content.replace(/\s+/g, " ").trim();

    if (current !== updated) {
        frm.set_value("ardtxt", final_content);
    }
}

