// ============================
// ✅ دالة إنشاء Quotation
// ============================
async function create_quotation(frm) {

    if (!frm.doc.party_name) {
        frappe.msgprint(__('يرجى تحديد العميل أولاً'));
        return;
    }

    if (!frm.doc.ard || frm.doc.ard.length === 0) {
        frappe.msgprint(__('لا توجد عناصر في جدول التسعيرة'));
        return;
    }

    try {
        let items = frm.doc.ard.map(row => ({
            item_code : row.item_codee,
            qty       : row.land_area  || 1,
            rate      : row.price_from || 0,
        }));

        let qtn = await frappe.db.insert({
            doctype          : 'Quotation',
            quotation_to     : frm.doc.quotation_to  || 'Customer',
            party_name       : frm.doc.party_name,
            transaction_date : frm.doc.التاريخ || frappe.datetime.get_today(),
            order_type       : frm.doc.order_typee   || '',
            customer_name    : frm.doc.customer_name || '',
            project_name     : frm.doc.project_name  || '',
            items            : items,
        });

        // ✅ رسالة جانبية
        frappe.show_alert({
            message  : __('تم إنشاء عرض الأسعار بنجاح: ') + qtn.name,
            indicator: 'green',
        }, 5);

        // ✅ فتح الـ Quotation مباشرة
        frappe.set_route('Form', 'Quotation', qtn.name);

    } catch (err) {
        frappe.show_alert({
            message  : __('حدث خطأ: ') + (err.message || err),
            indicator: 'red',
        }, 5);
    }
}
  


