                            max_price_to = rw.price_to;
                    });

                    text = text.replace(/{{price_from}}/g, min_price_from ?? 0);
                    text = text.replace(/{{price_to}}/g,   max_price_to   ?? 0);

                    text += `
                        <div style="margin-top:20px;text-align:right;">
                            <p><strong>السعر الإجمالي من:</strong> ${frm.doc.total_from || 0}</p>
                            <p><strong>السعر الإجمالي إلى:</strong> ${frm.doc.total_to  || 0}</p>
                        </div>
                    `;
                }

                final_content += `
                    <div style="margin-bottom:35px;text-align:right;clear:both;">
                        <div style="margin-bottom:12px;">
                            <span class="custom-title-box">${title}</span>
                        </div>
                        <div style="padding-right:15px;text-align:right;">${text}</div>
                    </div>
                `;
            }
        }
    }

    final_content += "</div>";

    if (readonly) return;

    const current = (frm.doc.ardtxt || "").replace(/\s+/g, " ").trim();
    const updated  = final_content.replace(/\s+/g, " ").trim();

    if (current !== updated) {
        frm.set_value("ardtxt", final_content);
    }
}

