// ============================
// إظهار/إخفاء + تعطيل فقط
// ============================
function toggle_mode(frm) {
    let pct = frm.doc.use_percentage;

    // إخفاء/إظهار الحقول
    frm.toggle_display('time_logs', !pct);
    frm.toggle_display('section_break_5', !pct);
    frm.toggle_display('working_hours', !pct);
    frm.toggle_display('total_hours', !pct);

    frm.toggle_display('completion_percentage', pct);
    frm.toggle_display('work_cost', pct);
    frm.toggle_display('activity_type', pct);

    if (pct) {
        disable_time_logs(frm);
    } else {
        enable_time_logs(frm);
    }

    frm.refresh_fields();
}

// ============================
// تعطيل الجدول فقط - بدون مسح
// ============================
function disable_time_logs(frm) {

    // تعطيل الجدول كاملاً
    frm.set_df_property('time_logs', 'read_only', 1);
    frm.set_df_property('time_logs', 'reqd', 0);

    // تعطيل المandatory وجعل كل حقل read only
    ['activity_type', 'from_time', 'to_time', 'hours'].forEach(function(field) {
        frm.fields_dict['time_logs'].grid.update_docfield_property(
            field, 'reqd', 0
        );
        frm.fields_dict['time_logs'].grid.update_docfield_property(
            field, 'read_only', 1
        );
    });

    // إخفاء زر Add Row
    frm.fields_dict['time_logs'].grid.cannot_add_rows = true;

    frm.refresh_field('time_logs');
}

// ============================
// إعادة تفعيل الجدول
// ============================
function enable_time_logs(frm) {

    frm.set_df_property('time_logs', 'read_only', 0);
    frm.set_df_property('time_logs', 'reqd', 0);

    ['activity_type', 'from_time', 'to_time', 'hours'].forEach(function(field) {
        frm.fields_dict['time_logs'].grid.update_docfield_property(
            field, 'reqd', 0
        );
        frm.fields_dict['time_logs'].grid.update_docfield_property(
            field, 'read_only', 0
        );
    });

    // إعادة زر Add Row
    frm.fields_dict['time_logs'].grid.cannot_add_rows = false;

    frm.refresh_field('time_logs');
}

// ============================
// جلب Costing Rate من Activity Cost
// ============================
function fetch_activity_cost(frm) {

    let activity_type = frm.doc.activity_type;

    if (!activity_type) {
        frappe.msgprint('الرجاء تحديد نوع العمل أولاً');
        return;
    }

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Activity Cost',
            filters: { activity_type: activity_type },
            fields: ['costing_rate'],
            limit_page_length: 1
        },
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                frm.set_value('work_cost', r.message[0].costing_rate);
            } else {
                frappe.msgprint('لا توجد تكلفة لنوع العمل: ' + activity_type);
            }
        }
    });
}

// ============================
// حساب الإجمالي في نفس الحقول
// ============================
function calc_total(frm) {
    let pct    = frm.doc.completion_percentage || 0;
    let cost   = frm.doc.work_cost || 0;
    let result = (pct / 100) * cost;

    frm.set_value('total_billable_amount', result);
    frm.set_value('base_total_billable_amount', result);
    frm.set_value('total_costing_amount', result);
    frm.set_value('base_total_costing_amount', result);
}

